#!/usr/bin/env python3
"""Generate the degree-keyword coverage fixture.

Writes degree-coverage.tex with one \\typeout DEGREECHECK marker per degree keyword, pairing the keyword with its expected submission wording. The CI compile step greps the log for every marker, so a keyword whose wording regresses fails the build naming the keyword.

Run from the repository root: python3 tests/smoke/gen-option-coverage.py
"""

from pathlib import Path

KEYWORDS_THESIS = ["phd", "mphil", "mres", "mscres", "engd", "profdoc"]
KEYWORDS_DISSERTATION = [
    "msc", "ma", "mba", "llm", "mmus", "pgcert",
    "pgdip", "bsc", "ba", "beng", "meng", "msci",
]


def main() -> None:
    lines = [
        "% !TeX program = pdflatex",
        "%%% Degree-keyword coverage: typeout markers per keyword,",
        "%%% asserted from the compile log. Generated by",
        "%%% tests/smoke/gen-option-coverage.py.",
        "\\documentclass[12pt,a4paper]{bangorthesis}",
        "\\title{Option Coverage}",
        "\\author{H. Student}",
        "\\degreescheme{Doctor of Philosophy}",
        "\\begin{document}",
        "word",
    ]
    for keyword in KEYWORDS_THESIS:
        lines.append(f"\\typeout{{DEGREECHECK:{keyword}:thesis}}")
    for keyword in KEYWORDS_DISSERTATION:
        lines.append(f"\\typeout{{DEGREECHECK:{keyword}:dissertation}}")
    lines.append("\\end{document}")
    out = Path(__file__).with_name("degree-coverage.tex")
    out.write_text("\n".join(lines) + "\n")
    print(f"wrote {out} with {len(KEYWORDS_THESIS) + len(KEYWORDS_DISSERTATION)} markers")


if __name__ == "__main__":
    main()
